from lib import *
S = SS('k14')
F1 = [['kubectl delete ns', 'phase = Terminating'], ['namespace 控制器', '逐个清理资源'], ['blocker', '带 finalizer'], ['conditions', '说明卡在哪']]
F2 = [['摘掉 blocker 的 finalizer', ''], ['内容清空', ''], ['摘掉 spec.finalizers: kubernetes', ''], ['命名空间消失', '4.2 秒']]
F3 = [['APIService', 'ServiceNotFound'], ['discovery 失败', 'k14.example.com/v1beta1'], ['k14b 卡在 Terminating', ''], ['删掉 APIService', '0.6 秒后消失']]
F4 = [['/finalize 清空 spec.finalizers', ''], ['命名空间消失', ''], ['etcd 里的 configmaps', '仍然在'], ['同名重建', '旧对象又出现']]
PANELS = [('f', 'flow', '命名空间的删除'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("命名空间 k14a 里有个带 example.com/block finalizer 的 ConfigMap。kubectl delete ns 返回 deleted,6 秒后仍是 Terminating,spec.finalizers=['kubernetes'],deletionTimestamp 已设置。status.conditions 里 NamespaceContentRemaining=True(Some resources are remaining: configmaps. has 1 resource instances)和 NamespaceFinalizersRemaining=True(example.com/block in 1 resource instances)直接说明了原因。", f=fl(F1, cur=[3], mark=[2], done=[0, 1]), t=tl(S(1), mark=lidx(S(1), 'NamespaceContentRemaining', 'NamespaceFinalizersRemaining'), done=lidx(S(1), 'phase=Terminating')), kv=KV([['Terminating', '已标记删除,还在清理里面的资源'], ['conditions', '五类情况,看 status=True 的那几个'], ['spec.finalizers', "只有 'kubernetes',由 namespace 控制器摘掉"]], ['conditions'])),
    step("摘掉 blocker 的 finalizer 之后,namespace 控制器清空了内容,命名空间在 4.2 秒内消失——不需要再动命名空间本身。", f=fl(F2, cur=[1], done=[0, 2, 3]), t=tl(S(2), mark=lidx(S(2), '4.2 秒')), kv=KV([['卡住时', '先找里面谁还带着 finalizer'], ['处理掉它', '命名空间自己会走完']], ['卡住时'])),
    step("另一类原因:APIService v1beta1.k14.example.com 指向不存在的 Service,AVAILABLE=False (ServiceNotFound)。命名空间 k14b 里只有一个普通 ConfigMap、没有 finalizer,8 秒后仍是 Terminating:NamespaceDeletionDiscoveryFailure=True,message “Discovery failed for some groups, 1 failing … k14.example.com/v1beta1”。删掉这个 APIService 之后,k14b 在 0.6 秒内消失。", f=fl(F3, cur=[2], mark=[1], done=[3]), t=tl(S(3), mark=lidx(S(3), 'DiscoveryFailed', 'ServiceNotFound'), done=lidx(S(3), '删掉这个 APIService 之后')), kv=KV([['DiscoveryFailure', '有 API 组不可用,无法确认内容清空'], ['常见来源', 'metrics-server 等聚合 API 挂了'], ['处理', '修好或删掉那个 APIService']], ['DiscoveryFailure'])),
    step("强行把命名空间的 spec.finalizers 清空(PUT /api/v1/namespaces/k14c/finalize):命名空间立即消失,但 etcd 里 /registry/configmaps/k14c/ 下还留着 blocker 和 kube-root-ca.crt;重新创建同名命名空间 k14c,kubectl get cm 又看到了这两个“幽灵”对象。", f=fl(F4, cur=[2], mark=[3], done=[0, 1]), t=tl(S(4), mark=lidx(S(4), 'etcd 里 /registry/configmaps/k14c/', '重新创建同名命名空间'), done=lidx(S(4), 'finalize')), kv=KV([['/finalize', '只改命名空间对象本身'], ['里面的对象', '留在 etcd 里,没有被清理'], ['同名重建', '旧对象会重新出现']], ['里面的对象'])),
]
A = mkartk('k14', 14, 'Kubernetes,Namespace,Terminating,finalizer,APIService,命名空间删不掉,真实验证,动画演示',
    '在 kind 集群里复现命名空间一直 Terminating 的两种原因并读出 status.conditions:里面有带 finalizer 的对象时 NamespaceContentRemaining 与 NamespaceFinalizersRemaining 为 True,摘掉 finalizer 后 4.2 秒内自行删除;某个 APIService 后端找不到时 NamespaceDeletionDiscoveryFailure 为 True,删掉 APIService 后 0.6 秒内消失;用 /finalize 强行摘掉命名空间 finalizer 会让里面的对象留在 etcd 里,重建同名命名空间时它们又出现。',
    '命名空间删了半天还是 Terminating,到底卡在哪一步?namespace 控制器把每一步的状态都写进了 status.conditions。这篇制造两种典型的卡住原因,读出对应的 condition,再试一次危险的“强制 finalize”,看它留下了什么后果。',
    [('NamespaceFinalizersRemaining', '里面有带 finalizer 的对象时为 True,message 指出了是哪个 finalizer、有几个对象'), ('DiscoveryFailed', '某个 APIService 不可用时,NamespaceDeletionDiscoveryFailure 的原因'), ('2 个', '/finalize 强删命名空间之后,etcd 里留下的对象数(重建同名命名空间时重新出现)')],
    [('里面有对象不肯走', '<p>删命名空间只是把 <code>phase</code> 设为 <code>Terminating</code>、<code>spec.finalizers</code> 里留着 <code>kubernetes</code>,然后由 namespace 控制器逐个清理里面的资源。ConfigMap <code>blocker</code> 带着自己的 finalizer,6 秒后命名空间还是 Terminating。<code>kubectl get ns -o yaml</code> 里 <code>status.conditions</code> 说得很清楚:<code>NamespaceContentRemaining</code>(<code>Some resources are remaining: configmaps. has 1 resource instances</code>)和 <code>NamespaceFinalizersRemaining</code>(<code>example.com/block in 1 resource instances</code>)为 True。</p>'),
     ('让那个对象走完', '<p>把 <code>blocker</code> 的 finalizer 摘掉,namespace 控制器清空内容后自己摘掉 <code>kubernetes</code>,命名空间在 4.2 秒内消失,全程没有动命名空间本身。排查原则:先看 condition,找到是谁在阻塞。</p>'),
     ('另一类:API 组不可用', '<p>命名空间里只有一个普通 ConfigMap,没有任何 finalizer,也会卡住:集群里有一个 <code>APIService</code> 指向不存在的 Service(<code>False (ServiceNotFound)</code>),namespace 控制器枚举不全所有 API 组,不敢确认内容已清空,<code>NamespaceDeletionDiscoveryFailure</code> 变成 True。删掉这个 APIService,命名空间 0.6 秒内就消失了。生产里常见的是 metrics-server 之类聚合 API 挂掉。</p>'),
     ('强行 finalize 的后果', '<p>网上常见的“把命名空间的 <code>spec.finalizers</code> 清空再 PUT 到 <code>/finalize</code>”确实能让命名空间立刻消失,但它绕过了清理:etcd 里 <code>/registry/configmaps/k14c/</code> 下的 <code>blocker</code> 和 <code>kube-root-ca.crt</code> 还在,重新创建同名命名空间,<code>kubectl get cm</code> 又看见它们。这是把症状按下去而不是解决原因。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);卡住用的 ConfigMap 带自己起名的 finalizer example.com/block;不可用的 APIService 指向 default 命名空间里不存在的 Service no-such-svc(insecureSkipTLSVerify);强制 finalize 用 kubectl replace --raw /api/v1/namespaces/<ns>/finalize;etcd 里的 key 用 etcdctl get --prefix --keys-only 读出;实验后清理了所有测试命名空间和 APIService;每种情形各一次',
     '没有验证:命名空间里有自定义资源且 CRD 先被删掉时的卡住情形;NamespaceDeletionContentFailure(内容删除失败,例如 webhook 拒绝删除);其他 spec.finalizers(如 Rancher、Istio 等加上的);namespace 控制器 --concurrent-namespace-syncs 的影响;命名空间里对象特别多时的耗时'],
    '命名空间的删除', PANELS)
